test.source:

class Point(final int x, var int y) {
  int sum() {
    return this.x + this.y;
  }
}

class Tag(final String name, {required final int weight, final String kind = 'k'}) {
  String describe() {
    return '${this.name}/${this.kind}/${this.weight}';
  }
}

class Counter(var count);

int run() {
  var p = Point(3, 4);
  p.y = 10;

  var c = Counter(1);
  c.count = c.count + 5;

  return p.sum() + c.count;
}

String describe() {
  var t = Tag('t', weight: 7);
  return t.describe();
}
